importScripts('geometry.js','detector-core.js');
let gray=null,mask=null,chromaA=null,chromaB=null,W=0,H=0;
self.onmessage=async({data})=>{const{id,type,bitmap,outer,points,edge,range,innerOptions}=data;let detectedOuter=null;try{
if(type==='load'){W=bitmap.width;H=bitmap.height;gray=new Uint8Array(W*H);mask=new Uint8Array(W*H);chromaA=new Uint8Array(W*H);chromaB=new Uint8Array(W*H);const tileH=Math.min(256,H);const c=new OffscreenCanvas(W,tileH),ctx=c.getContext('2d',{willReadFrequently:true});let sr=0,sg=0,sb=0,n=0,s2=0;const band=Math.max(2,Math.min(12,Math.floor(Math.min(W,H)*.005)));
for(let y=0;y<H;y+=tileH){const hh=Math.min(tileH,H-y);ctx.clearRect(0,0,W,tileH);ctx.drawImage(bitmap,0,y,W,hh,0,0,W,hh);const p=ctx.getImageData(0,0,W,hh).data;for(let yy=0;yy<hh;yy++)for(let x=0;x<W;x++){if(y+yy>=band&&y+yy<H-band&&x>=band&&x<W-band)continue;const k=(yy*W+x)*4;sr+=p[k];sg+=p[k+1];sb+=p[k+2];s2+=p[k]*p[k]+p[k+1]*p[k+1]+p[k+2]*p[k+2];n++;}}
const bg=[sr/n,sg/n,sb/n],variance=Math.max(0,s2/n-bg.reduce((s,v)=>s+v*v,0)),threshold=Math.max(25,Math.min(105,Math.sqrt(variance)*2.2+22));
for(let y=0;y<H;y+=tileH){const hh=Math.min(tileH,H-y);ctx.drawImage(bitmap,0,y,W,hh,0,0,W,hh);const p=ctx.getImageData(0,0,W,hh).data;for(let i=0;i<W*hh;i++){const k=i*4,j=y*W+i;gray[j]=Math.round(.299*p[k]+.587*p[k+1]+.114*p[k+2]);chromaA[j]=Math.round((p[k]-p[k+2]+255)/2);chromaB[j]=Math.round((2*p[k+1]-p[k]-p[k+2]+510)/4);mask[j]=Math.hypot(p[k]-bg[0],p[k+1]-bg[1],p[k+2]-bg[2])>threshold?1:0;}self.postMessage({id,progress:Math.round((y+hh)/H*70),label:'逐像素读取原图与颜色边缘'});}bitmap.close();self.postMessage({id,loaded:true,width:W,height:H});return;}
if(!gray)throw Error('请先上传图片');if(type==='edge'){self.postMessage({id,progress:82,label:'连续边缘检测与稳健直线拟合'});self.postMessage({id,result:CenterDetector.refineEdge(gray,W,H,points,edge,range,[chromaA,chromaB])});return;}
self.postMessage({id,progress:78,label:'排除圆角并逐边拟合外框'});const out=outer?{outer,quality:null}:CenterDetector.detectOuter(gray,mask,W,H,[chromaA,chromaB]);detectedOuter=out.outer;self.postMessage({id,progress:88,label:'按参考比例搜索连续水平与竖直内边界'});const innerResult=CenterDetector.detectInner(gray,W,H,out.outer,[chromaA,chromaB],innerOptions);self.postMessage({id,result:{outer:out.outer,...innerResult,outerQuality:out.quality,width:W,height:H}});
}catch(e){self.postMessage({id,error:e.message||'识别失败，请手动定位',partial:detectedOuter?{outer:detectedOuter}:null});}};
